grant select on public.organizations,public.organization_members to authenticated;
create policy org_read on public.organizations for select to authenticated using(private.is_org_member(id));
create policy member_read on public.organization_members for select to authenticated using(private.is_org_member(organization_id));
create policy matter_read on public.matters for select to authenticated using(private.is_org_member(organization_id) and (not is_restricted or created_by=auth.uid() or exists(select 1 from public.matter_members mm where mm.matter_id=matters.id and mm.user_id=auth.uid())));
create policy matter_insert on public.matters for insert to authenticated with check(private.is_org_member(organization_id) and created_by=auth.uid());
create policy matter_update on public.matters for update to authenticated using(private.has_matter_access(id)) with check(private.is_org_member(organization_id) and private.has_matter_access(id));
create policy matter_members_read on public.matter_members for select to authenticated using(private.has_matter_access(matter_id));
grant select,insert,update on public.matters to authenticated;
grant select on public.matter_members to authenticated;
create policy documents_read on public.documents for select to authenticated using((private.is_org_member(organization_id) and (matter_id is null or private.has_matter_access(matter_id))) or private.shared_resource('document',id));
create policy documents_insert on public.documents for insert to authenticated with check(private.is_org_member(organization_id) and uploaded_by=auth.uid() and (matter_id is null or private.has_matter_access(matter_id)));
create policy documents_update on public.documents for update to authenticated using(private.is_org_member(organization_id) and (matter_id is null or private.has_matter_access(matter_id))) with check(private.is_org_member(organization_id) and (matter_id is null or private.has_matter_access(matter_id)));
create policy documents_delete on public.documents for delete to authenticated using(private.is_org_member(organization_id) and (matter_id is null or private.has_matter_access(matter_id)) and (uploaded_by=auth.uid() or private.org_role_for(organization_id) in ('owner','admin','partner')));
